"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Wild Call', 'author': 'Signature original', 'genre': 'Mountain Quests', 'chapters': [{'n': 1, 'title': 'The Call of the Wild', 'text': "They made camp under strange stars. a carved obelisk key pulsed on Casey Drake's chest. Somewhere out there, the mercenary Voss was moving. The race, Casey Drake thought, was already on. fortune favors the bold — time to prove it.\n\nCasey Drake was fixing an engine when a carved obelisk key arrived — by courier, no return address, with a note: 'You know what this is. Come to the Siberian taiga. Hurry.' Casey Drake knew. Everyone in their line knew the legend.\n\nBy dawn they were over the Siberian taiga, the green unrolling below like a held breath. Casey Drake checked a carved obelisk key one more time. It hummed faintly, the way true things do when they're near their home."}, {'n': 2, 'title': 'Into the Green', 'text': "At dawn the markers led to the ruins: stone teeth in the jungle's jaw. Casey Drake stood at the gate with a carved obelisk key humming louder. 'Whatever happens,' Casey Drake said, 'we go together.'\n\nThe rapids nearly ended it: rapids, a broken rope, Casey Drake in the water with a carved obelisk key in a waterproof bag and the pilot Anya's hand the only solid thing in the world. 'Never leave a friend behind,' the pilot Anya gasped. 'Your rule.'\n\nThree days into the Siberian taiga, the trail went cold — and then hot: fresh boot prints, the mercenary Voss's mark, heading the same way. 'They're a day ahead,' the pilot Anya said, 'but they're heavy. We're fast.'"}, {'n': 3, 'title': 'The Ruins', 'text': "Casey Drake took it and ran, because Casey Drake is not an idiot. The chase through the collapsing ruins was the kind of thing they'd tell for years: swinging, sliding, the pilot Anya with the rope, a carved obelisk key in the bag, the whole place coming down.\n\nthe mercenary Voss's team hit them in the treasure chamber — of course it was the treasure chamber — and the standoff was pure cinema: a carved obelisk key on its pedestal, two crews, one exit. 'Take it,' the mercenary Voss said, 'and die rich.'\n\nInside: wonders. the pilot Anya, the scholar at heart, wept at the murals. Casey Drake kept watch, because wonders in such places usually have teeth. They did: the floor was a trap, the walls were a trap, the air was a trap."}, {'n': 4, 'title': 'The Price of Gold', 'text': "The backup team wasn't loyal — just paid. When Casey Drake offered them the truth about the mercenary Voss's promises (empty) versus a share of the legitimate expedition rights (real), they lowered their weapons. Money talks. Truth talks louder.\n\nAt the canyon, they made their stand: outnumbered, outgunned, but holding the high ground and the moral ground, which as the pilot Anya said weakly, 'is worth at least two guns.'\n\nthe mercenary Voss, bound and furious, offered everything: money, power, a share. Casey Drake listened politely and said no politely, which infuriated the mercenary Voss more than any insult. Some people can't be bought. Some treasures can't be sold."}, {'n': 5, 'title': 'The Real Treasure', 'text': "the mercenary Voss got fifteen years and a memoir deal. Casey Drake got the kid's wide eyes and the pilot Anya's friendship and a new map already arriving by courier. No return address. Of course.\n\nfortune favors the bold — Casey Drake wrote it in the expedition log, under the date, under the coordinates of the Siberian taiga. Then closed the book. Then opened the new map.\n\nA kid asked Casey Drake if it was worth it — the danger, the lost years. Casey Drake thought of the river, the ruins, the pilot Anya's hand in the rapids. 'The thing,' Casey Drake said, 'was never the thing.'"}, {'n': 6, 'title': 'Next Horizon', 'text': "Engines up. fortune favors the bold. The horizon, as always, was just the beginning.\n\nThe plane — or boat, or truck, or camel — was already arranged. It always is, when a carved obelisk key calls. That's the thing about legends: they don't end. They just wait for the next believer.\n\nthe pilot Anya was packed before Casey Drake finished reading the note. 'Where to?' the pilot Anya asked. Casey Drake pointed at the map's edge, past the Siberian taiga, past everything known. 'There,' Casey Drake said."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

